18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.samples.petclinic.rest.error.InvalidTelephoneException;
34	import org.springframework.samples.petclinic.rest.error.RequiredFieldsMissingException;
35	import org.springframework.security.access.AccessDeniedException;
36	import org.springframework.validation.BindingResult;
37	import org.springframework.web.bind.MethodArgumentNotValidException;
38	import org.springframework.web.bind.annotation.ControllerAdvice;
39	import org.springframework.web.bind.annotation.ExceptionHandler;
40	import org.springframework.web.bind.annotation.ResponseBody;
41	
42	/**
43	 * Global Exception handler for REST controllers.
44	 * <p>
45	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
46	 *
47	 * @author Vitaliy Fedoriv
48	 * @author Alexander Dudkin
49	 */
50	@ControllerAdvice
51	public class ExceptionControllerAdvice {
52	
53	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
54	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
55	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
56	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
57	
58	    /**
59	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
60	     * class.
61	     *
62	     * @param e     Object referring to the thrown exception.
63	     * @param status HTTP response status.
64	     * @param url URL request.
65	     */
66	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
67	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
68	        problemDetail.setType(URI.create(url.toString()));
69	        problemDetail.setTitle(e.getClass().getSimpleName());
70	        problemDetail.setDetail(detail);
71	        problemDetail.setProperty("timestamp", Instant.now());
72	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
73	        return problemDetail;
74	    }
75	
76	    /**
77	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
78	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
79	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
80	     * would catch it and report an authorization failure as a 500.
81	     *
82	     * @param e The {@link AccessDeniedException} to propagate
83	     * @throws AccessDeniedException always
84	     */
85	    @ExceptionHandler(AccessDeniedException.class)
86	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
87	        throw e;
88	    }
89	
90	    /**
91	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
92	     *
93	     * @param e The {@link Exception} to be handled
94	     * @param request {@link HttpServletRequest} object referring to the current request.
95	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
96	     */
97	    @ExceptionHandler(Exception.class)
98	    @ResponseBody
99	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
100	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
101	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
102	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
103	        return ResponseEntity.status(status).body(detail);
104	    }
105	
106	    /**
107	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
108	     * method returns a 404 Not Found status if an entity does not exist.
109	     *
110	     * @param e The {@link DataIntegrityViolationException} to be handled
111	     * @param request {@link HttpServletRequest} object referring to the current request.
112	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
113	     */
114	    @ExceptionHandler(DataIntegrityViolationException.class)
115	    @ResponseBody
116	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
117	        logger.warn("Data integrity violation at {} {}: {}",
118	            request.getMethod(),
119	            request.getRequestURI(),
120	            e.getMessage());
121	        logger.debug("Data integrity violation stacktrace", e);
122	        HttpStatus status = HttpStatus.NOT_FOUND;
123	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
124	        return ResponseEntity.status(status).body(detail);
125	    }
126	
127	    /**
128	     * Handles exception thrown by Bean Validation on controller methods parameters
129	     *
130	     * @param e The {@link MethodArgumentNotValidException} to be handled
131	     * @param request {@link HttpServletRequest} object referring to the current request.
132	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
133	     */
134	    @ExceptionHandler(MethodArgumentNotValidException.class)
135	    @ResponseBody
136	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
137	        HttpStatus status = HttpStatus.BAD_REQUEST;
138	        BindingErrorsResponse errors = new BindingErrorsResponse();
139	        BindingResult bindingResult = e.getBindingResult();
140	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
141	        if (bindingResult.hasErrors()) {
142	            errors.addAllErrors(bindingResult);
143	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
144	                .map(fieldError -> fieldError.getField())
145	                .distinct()
146	                .toList();
147	            detail.setProperty("errors", invalidFields);
148	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
149	                .map(fieldError -> {
150	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
151	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
152	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
153	                        fieldError.getField(),
154	                        defaultMessage,
155	                        rejectedValue);
156	                    return new ValidationMessageDto(message)
157	                        .putAdditionalProperty("field", fieldError.getField())
158	                        .putAdditionalProperty("rejectedValue", rejectedValue)
159	                        .putAdditionalProperty("defaultMessage", defaultMessage);
160	                })
161	                .toList();
162	            logger.debug("Validation error at {} {}: {}",
163	                request.getMethod(),
164	                request.getRequestURI(),
165	                bindingResult.getFieldErrors());
166	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
167	            return ResponseEntity.status(status).body(detail);
168	        }
169	        return ResponseEntity.status(status).body(detail);
170	    }
171	
172	    /**
173	     * Handles {@link RequiredFieldsMissingException} thrown when a request omits or leaves blank a
174	     * mandatory field. Returns a 400 Bad Request whose {@code errors} array names each missing field.
175	     *
176	     * @param e The {@link RequiredFieldsMissingException} to be handled
177	     * @param request {@link HttpServletRequest} object referring to the current request.
178	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
179	     */
180	    @ExceptionHandler(RequiredFieldsMissingException.class)
181	    @ResponseBody
182	    public ResponseEntity<ProblemDetail> handleRequiredFieldsMissingException(RequiredFieldsMissingException e, HttpServletRequest request) {
183	        logger.debug("Missing required fields at {} {}: {}",
184	            request.getMethod(),
185	            request.getRequestURI(),
186	            e.getMissingFields());
187	        HttpStatus status = HttpStatus.BAD_REQUEST;
188	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
189	        detail.setProperty("errors", e.getMissingFields());
190	        return ResponseEntity.status(status).body(detail);
191	    }
192	
193	    /**
194	     * Handles {@link InvalidTelephoneException} thrown when a submitted telephone number does not
195	     * contain exactly ten digits once every non-digit character has been stripped. Returns a
196	     * 400 Bad Request naming the offending field.
197	     *
198	     * @param e The {@link InvalidTelephoneException} to be handled
199	     * @param request {@link HttpServletRequest} object referring to the current request.
200	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
201	     */
202	    @ExceptionHandler(InvalidTelephoneException.class)
203	    @ResponseBody
204	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
205	        logger.debug("Invalid telephone at {} {}: {}",
206	            request.getMethod(),
207	            request.getRequestURI(),
208	            e.getRejectedValue());
209	        HttpStatus status = HttpStatus.BAD_REQUEST;
210	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
211	        detail.setProperty("errors", List.of("telephone"));
212	        return ResponseEntity.status(status).body(detail);
213	    }
214	
215	}
